import json, os, time, urllib.request, urllib.parse, urllib.error
base=os.environ['GALAXY_URL'].rstrip('/')
with open(os.environ['GALAXY_API_KEY_FILE']) as f:
    key=f.read().strip()
history='bbd44e69cb8906b55466491a12cab066'
tool='toolshed.g2.bx.psu.edu/repos/iuc/anndata_inspect/anndata_inspect/0.11.4+galaxy3'
ref='f9cad7b01a472135ffce3659fb74d0d7'
query='f9cad7b01a472135c3963a2b14b8ca41'
jobs=[('ref_obs',ref,'obs'),('ref_var',ref,'var'),('query_obs',query,'obs'),('query_general',query,'general')]

def req(method,path,data=None):
    url=base+path
    body=None
    headers={'x-api-key':key}
    if data is not None:
        body=json.dumps(data).encode()
        headers['Content-Type']='application/json'
    r=urllib.request.Request(url, data=body, headers=headers, method=method)
    with urllib.request.urlopen(r, timeout=60) as resp:
        return json.loads(resp.read().decode())

submitted=[]
for label, ds, info in jobs:
    payload={
        'history_id': history,
        'tool_id': tool,
        'input_format': '21.01',
        'inputs': {'input': {'src':'hda','id':ds}, 'inspect': {'info': info}}
    }
    out=req('POST','/api/tools',payload)
    job_ids=[j['id'] for j in out.get('jobs',[])]
    outputs={k:v['id'] for k,v in out.get('outputs',{}).items()}
    print(json.dumps({'label':label,'jobs':job_ids,'outputs':outputs}), flush=True)
    submitted.append((label, job_ids, outputs))

pending={jid:label for label,jids,outs in submitted for jid in jids}
terminal={'ok','error','deleted'}
while pending:
    done=[]
    for jid,label in pending.items():
        job=req('GET',f'/api/jobs/{jid}')
        state=job.get('state')
        if state in terminal:
            print(json.dumps({'label':label,'job':jid,'state':state}), flush=True)
            done.append(jid)
            if state"'!='"'ok':
                print(json.dumps({'job_details':job}), flush=True)
    for jid in done:
        pending.pop(jid,None)
    if pending:
        time.sleep(10)
print('ALL_TERMINAL', flush=True)
PY"

