import h5py, numpy as np, scipy.sparse as sp, math
from collections import Counter, defaultdict
from scipy.optimize import linear_sum_assignment
from scipy.stats import pearsonr, spearmanr

def read_str_array(obj):
    if isinstance(obj,h5py.Dataset):
        arr=obj[()]
        return np.array([x.decode() if isinstance(x,(bytes,bytearray)) else str(x) for x in arr], dtype=object)
    codes=obj['codes'][()]
    cats=read_str_array(obj['categories'])
    return np.array([cats[i] if i>=0 else None for i in codes], dtype=object)
def load(fn):
    with h5py.File(fn,'r') as f:
        shape=tuple(f['X'].attrs['shape'])
        X=sp.csc_matrix((f['X/data'][()], f['X/indices'][()], f['X/indptr'][()]), shape=shape).tocsr()
        var=read_str_array(f['var/_index'])
        obs={k:read_str_array(f['obs/'+k]) for k in f['obs'].keys() if k"'!='"'_index'}
    return X,var,obs
R,Rvar,Robs=load('inputs/perturb.seq.align.q1.ref.h5ad')
Q,Qvar,Qobs=load('inputs/perturb.seq.align.q1.query.h5ad')
# common genes and reorder columns
common=sorted(set(Rvar)&set(Qvar))
Ri=np.array([np.where(Rvar==g)[0][0] for g in common])
Qi=np.array([np.where(Qvar==g)[0][0] for g in common])
R=R[:,Ri]; Q=Q[:,Qi]
# guide lists
Rguides=np.array(Robs['guide']); Rtarg=np.array(Robs['target_gene']); Qguides=np.array(Qobs['guide'])
Rlist=sorted([g for g in set(Rguides) if not g.startswith('NT')])
Qlist=sorted([g for g in set(Qguides) if g.startswith('guide')], key=lambda s:int(s[5:]))
Rtarget={g:Counter(Rtarg[Rguides==g]).most_common(1)[0][0] for g in Rlist}
# transform options: original, log1p if values look counts? Values probably normalized/log.
print('value stats R', R.data[:100000].min(), R.data[:100000].max(), np.quantile(R.data[:100000],[.1,.5,.9]))
print('value stats Q', Q.data[:100000].min(), Q.data[:100000].max(), np.quantile(Q.data[:100000],[.1,.5,.9]))

def group_means(X, guides, glist):
    out={}
    for g in glist:
        idx=np.where(guides==g)[0]
        out[g]=np.asarray(X[idx].mean(axis=0)).ravel()
    return out
Rmeans=group_means(R,Rguides,Rlist+[g for g in sorted(set(Rguides)) if g.startswith('NT')])
Qmeans=group_means(Q,Qguides,Qlist+[g for g in sorted(set(Qguides)) if g.startswith('NT')])
Rnt=np.mean([Rmeans[g] for g in Rmeans if g.startswith('NT')],axis=0)
Qnt=np.mean([Qmeans[g] for g in Qmeans if g.startswith('NT')],axis=0)
# variances for gene filtering
Rall=np.asarray(R.mean(axis=0)).ravel(); Qall=np.asarray(Q.mean(axis=0)).ravel()
# compute effect variants
variants={}
for center in ['nt','global']:
    Reff={g:Rmeans[g]-(Rnt if center=='nt' else Rall) for g in Rlist}
    Qeff={g:Qmeans[g]-(Qnt if center=='nt' else Qall) for g in Qlist}
    variants[center]=(Reff,Qeff)
# gene filters by high abs effects in reference/query union per pair. Also global var approximate from means? Use nonzero enough.
def corr(a,b,method='pearson'):
    if method=='cos':
        na=np.linalg.norm(a); nb=np.linalg.norm(b); return float(a.dot(b)/(na*nb)) if na and nb else -9
    if np.std(a)==0 or np.std(b)==0: return -9
    return float(np.corrcoef(a,b)[0,1])
for center,(Reff,Qeff) in variants.items():
  for scale in ['raw','zgenes']:
    # z-scale effects across ref guides and query guides separately per gene to reduce gene variance bias
    RR=np.vstack([Reff[g] for g in Rlist]); QQ=np.vstack([Qeff[g] for g in Qlist])
    if scale=='zgenes':
        Rs=RR.std(axis=0); Qs=QQ.std(axis=0); Rs[Rs==0]=1; Qs[Qs==0]=1
        Re={g:(Reff[g]/Rs) for g in Rlist}; Qe={g:(Qeff[g]/Qs) for g in Qlist}
    else:
