      targets={t:assign.get(next(g for g in Rlist if Rtarget[g]==t)) for t in ['PABPC1','NUDT21','LEO1']}
      print('ASSIGN',center,scale,metric,targets,'total',round(mat[rows,cols].sum(),3))
