        top=sorted([(mat[Rlist.index(rg),j],Qlist[j]) for j in range(len(Qlist))], reverse=True)[:8]
        print(' ',t,[(q,round(s,4)) for s,q in top])
# Try top variable/effect genes per pair zscaled cosine
print('TOP-K pair union effects')
for center,(Reff,Qeff) in variants.items():
  for k in [100,300,1000,3000]:
    mat=[]
    for rg in Rlist:
      row=[]
      for qg in Qlist:
        a=Reff[rg]; b=Qeff[qg]
        idx=np.argpartition(-(np.abs(a)+np.abs(b)), min(k,len(a)-1))[:k]
