/bin/bash -lc "python - <<'PY'
# Print normalized-log NT-centered Pearson assignment and margins for requested targets.
import h5py, numpy as np, scipy.sparse as sp
from collections import Counter
from scipy.optimize import linear_sum_assignment

def read(obj):
    if isinstance(obj,h5py.Dataset):
        return np.array([x.decode() if isinstance(x,(bytes,bytearray)) else str(x) for x in obj[()]], dtype=object)
    codes=obj['codes'][()]; cats=read(obj['categories']); return np.array([cats[i] for i in codes], dtype=object)
def load(fn):
    with h5py.File(fn,'r') as f:
        shape=tuple(f['X'].attrs['shape'])
        X=sp.csc_matrix((f['X/data'][()].astype(float), f['X/indices'][()], f['X/indptr'][()]), shape=shape).tocsr()
        var=read(f['var/_index']); obs={k:read(f['obs/'+k]) for k in f['obs'] if k"'!='"'_index'}
    return X,var,obs
def norm(X):
    total=np.asarray(X.sum(axis=1)).ravel(); total[total==0]=1
    Y=sp.diags(1e4/total).dot(X).tocsr(); Y.data=np.log1p(Y.data); return Y
def means(X,guides,glist):
    return {g:np.asarray(X[np.where(guides==g)[0]].mean(axis=0)).ravel() for g in glist}
def pcorr(a,b):
    if a.std()==0 or b.std()==0: return -9
    return float(np.corrcoef(a,b)[0,1])
R,Rv,Ro=load('inputs/perturb.seq.align.q1.ref.h5ad'); Q,Qv,Qo=load('inputs/perturb.seq.align.q1.query.h5ad')
common=sorted(set(Rv)&set(Qv)); Rmap={g:i for i,g in enumerate(Rv)}; Qmap={g:i for i,g in enumerate(Qv)}
R=norm(R[:,[Rmap[g] for g in common]]); Q=norm(Q[:,[Qmap[g] for g in common]])
Rg=Ro['guide']; Rt=Ro['target_gene']; Qg=Qo['guide']
Rlist=sorted([g for g in set(Rg) if not g.startswith('NT')]); Qlist=sorted([g for g in set(Qg) if g.startswith('guide')], key=lambda s:int(s[5:]))
Rnt=sorted([g for g in set(Rg) if g.startswith('NT')]); Qnt=sorted([g for g in set(Qg) if g.startswith('NT')])
Rm=means(R,Rg,Rlist+Rnt); Qm=means(Q,Qg,Qlist+Qnt)
Rbase=np.average([Rm[g] for g in Rnt], axis=0, weights=[(Rg==g).sum() for g in Rnt]); Qbase=np.average([Qm[g] for g in Qnt], axis=0, weights=[(Qg==g).sum() for g in Qnt])
Re={g:Rm[g]-Rbase for g in Rlist}; Qe={g:Qm[g]-Qbase for g in Qlist}
mat=np.array([[pcorr(Re[r],Qe[q]) for q in Qlist] for r in Rlist])
rows,cols=linear_sum_assignment(-mat); assign={Rlist[i]:Qlist[j] for i,j in zip(rows,cols)}
Rtarget={g:Counter(Rt[Rg==g]).most_common(1)[0][0] for g in Rlist}
for target in ['PABPC1','NUDT21','LEO1']:
    rg=next(g for g in Rlist if Rtarget[g]==target); i=Rlist.index(rg)
    top=sorted([(mat[i,j],Qlist[j]) for j in range(len(Qlist))], reverse=True)[:5]
    print(target, rg, 'assigned', assign.get(rg), 'top', [(q,round(s,4)) for s,q in top])
PY"

